import { useQuery } from '@tanstack/react-query';

// Define types based on your database schema
export interface PrepItem {
  prepItemId: number;
  prepItemName: string;
  description: string;
  itemCategory: number;
  kitchenDepartmentId: number;
  restaurantId: number;
}

export interface PrepItemIngredient {
  prepIngredientId: number;
  prepItemId: number;
  ingredientId: number;
  quantity: number;
  unit: string;
  ingredient?: Ingredient; // For joined data
}

export interface Ingredient {
  ingredientId: number;
  ingredientName: string;
  unit: string;
  unitPrice: number;
  category: string;
}

export interface Recipe extends PrepItem {
  ingredients: PrepItemIngredient[];
  procedure: string; // This might be stored elsewhere or as part of description
}

