// Fetch recipes with their ingredients
export const useRecipes = (restaurantId?: number) => {
  return useQuery({
    queryKey: ['recipes', restaurantId],
    queryFn: async (): Promise<Recipe[]> => {
      // Return mock data for now
      return mockRecipes;
    },
    enabled: !!restaurantId
  });
};

// Fetch a single recipe with detailed information
export const useRecipe = (recipeId?: number) => {
  return useQuery({
    queryKey: ['recipe', recipeId],
    queryFn: async (): Promise<Recipe> => {
      // Return mock data for now
      const recipe = mockRecipes.find(recipe => recipe.prepItemId === recipeId);
      if (!recipe) {
        throw new Error('Recipe not found');
      }
      return recipe;
    },
    enabled: !!recipeId
  });
}; 